function e(e){e.forEach(e=>{const t=e.querySelector('[data-hero="line-track"]'),r=e.querySelector('[data-hero="line-fill"]');if(!t||!r)return;gsap.set(r,{scaleY:0,transformOrigin:"top center"});const a=ScrollTrigger.create({trigger:t,start:"top 80%",end:"bottom 50%"});let o=0;gsap.ticker.add(()=>{const e=a.progress-o;Math.abs(e)<1e-4||(o+=.08*e,gsap.set(r,{scaleY:o}))})})}export{e as default};
